import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;public record ThreadPoolConfig() {    private static final Integer CORE_THREAD = 10;    private static final Integer MAX_THREAD = 50;    private static final Long KEEP_TIME = 120L;    private static final TimeUnit TIME_UNIT = TimeUnit.SECONDS;    private static final Integer QUEUE_CAPACITY = 10;    public static ThreadPoolExecutor createDownloadPool(){        return new ThreadPoolExecutor(            CORE_THREAD,            MAX_THREAD,            KEEP_TIME,            TIME_UNIT,            new ArrayBlockingQueue<>(QUEUE_CAPACITY),            new ThreadFactory(){                private final AtomicInteger atomicInteger = new AtomicInteger(0);                @Override                public Thread newThread(Runnable r){                    int i = atomicInteger.incrementAndGet();                    Thread t = new Thread(r);                    t.setName("createThread" + i);                    return t;                }            },            new ThreadPoolExecutor.CallerRunsPolicy()        );    }}